func redact(line string) string {
	fields := regexp.MustCompile(`(^|[[:space:]])(email|token)=[^[:space:]]+`)
	return fields.ReplaceAllStringFunc(line, func(field string) string {
		key, _, _ := strings.Cut(field, "=")
		return key + "=***"
	})
}

